head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > independentPanel]<br/>Accordion 컴포넌트의 패널을 독립적으로 열고 닫을지 설정합니다.",
    "validation" : [
        "independentPanel=true 설정 시 각 패널이 서로 영향을 주지 않고 독립적으로 열기/닫기를 수행합니다.",
        "independentPanel=true 설정 시 다른 열린 패널이 닫히지 않으므로 여러 패널을 동시에 열 수 있습니다.",
        "independentPanel=false (default) 설정 시 하나의 패널을 열 때 기존에 열려 있던 다른 패널이 자동으로 닫히는 배타적 모드로 동작합니다.",
        "independentPanel=false (default) 설정 시 패널 열기 동작으로 다른 열린 패널이 닫히면서 onpanelunload 이벤트가 발생합니다.",
        "independentPanel=false 이면 타이틀을 클릭하여 패널을 열 때 onpanelunload(다른 패널) → onclick → onpanelload 순서로 이벤트가 발생합니다.",
        "independentPanel 속성을 생략하면 기본값 false 로 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (collapsible=true 로 고정하여 closePanel / 다중 열기 동작 비교가 용이하도록 구성)
    let properties = {
        independentPanel : con_independentPanel.getText(),
        collapsible : "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* independentPanel=true : 각 패널이 독립적으로 열기/닫기, 다른 열린 패널이 닫히지 않아 여러 패널 동시 열기 가능"', '', 'label1');
    $c.gcm.createLabel('label="* independentPanel=false (default) : 하나의 패널을 열 때 기존 열린 패널이 자동으로 닫히는 배타적 모드 동작 (다른 패널 닫힘 → onpanelunload 발생)"', '', 'label2');
    $c.gcm.createLabel('label="* independentPanel=false 환경에서 사용자가 panelTitle 클릭하여 패널을 열 때 onpanelunload(다른 패널) → onclick → onpanelload 순서로 이벤트 발생"', '', 'label3');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="" userID="userPanel1">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="" userID="userPanel2">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="" userID="userPanel3">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onclick 핸들러 — 가이드 @param : <Object> panel, <boolean> open
scwin.target1_onclick = function (panel, open) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onclick 이벤트 발생]");
};



// onpanelload 핸들러 — 가이드 @param : <String> panelID, <String> userID
scwin.target1_onpanelload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생]");
};



// onpanelunload 핸들러 — 가이드 @param : <String> panelID, <String> userID
scwin.target1_onpanelunload = function (panelID, userID) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생]");
};



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
